/* prog55_connected_components.c
 * Reimplementation of the original binary's behaviour.
 * The program reads a graph description from the command line,
 * checks the input, computes connected components with BFS,
 * and prints them in the format:
 *
 *   <size>: {v0,v1,...,vk}
 *
 * If the input is invalid the program prints "INVALID_INPUT"
 * (followed by a newline) and exits with status 1.
 *
 * The graph is limited to at most 8 vertices and 8 edges,
 * exactly as the original binary enforced.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8          /* maximum number of vertices */
#define MAXE 8          /* maximum number of edges */

int main(int argc, char *argv[])
{
    int n, m;                     /* number of vertices and edges */
    int adj[MAXV][MAXV] = {{0}};  /* adjacency matrix */
    int visited[MAXV] = {0};
    int queue[MAXV];
    int component[MAXV];
    int i, u, v;

    /* ---------- input validation ---------- */
    if (argc < 3) {                     /* need at least n and m */
        puts("INVALID_INPUT");
        return 1;
    }

    n = (int)strtol(argv[1], NULL, 10);
    m = (int)strtol(argv[2], NULL, 10);

    if (n < 0 || n >= MAXV || m < 0 || m >= MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }

    if (argc != 3 + 2 * m) {            /* exactly 2*m numbers after n,m */
        puts("INVALID_INPUT");
        return 1;
    }

    for (i = 0; i < m; ++i) {
        u = (int)strtol(argv[3 + 2 * i], NULL, 10);
        v = (int)strtol(argv[3 + 2 * i + 1], NULL, 10);
        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }
        adj[u][v] = 1;
        adj[v][u] = 1;                  /* undirected graph */
    }

    /* ---------- BFS to find components ---------- */
    for (i = 0; i < n; ++i) {
        if (visited[i])
            continue;                  /* already part of a component */

        /* start a new component */
        int qhead = 0, qtail = 0, comp_sz = 0;

        visited[i] = 1;
        queue[qtail++] = i;

        while (qhead < qtail) {
            int cur = queue[qhead++];
            component[comp_sz++] = cur;

            for (int nb = 0; nb < n; ++nb) {
                if (adj[cur][nb] && !visited[nb]) {
                    visited[nb] = 1;
                    queue[qtail++] = nb;
                }
            }
        }

        /* ---------- output the component ---------- */
        printf("%d:", comp_sz);
        printf(" {");
        for (int k = 0; k < comp_sz; ++k) {
            if (k > 0)
                putchar(',');
            printf("%d", component[k]);
        }
        putchar('}');
        putchar('\n');
    }

    return 0;
}
